/// <summary>
/// handle buttons related to sales order form
/// </summary>
[ExtensionOf(classStr(SalesTableInteraction))]
Public final class METSalesTableInteraction_Extension
{
    
    #localmacro.SetEnabled
        macroFormControlStr = %1;
        if (page.actionPaneControlVisible(macroFormControlStr))
        {
            page.actionPaneControlEnabled(macroFormControlStr, %2);
        }
    #endmacro

}

Method.Source:
    /// </summary>
    /// MPJ_24819_SOParametersAndCancelLinePickList
    /// Control “Remove”, “Add Line”, ”Add Products” and “Add Lines” buttons
    /// </summary>
    protected void enableLineFunctionActions()
    {
        next enableLineFunctionActions();

        if(METCustParameters::find().DisableSOLineEdit)
        {
            boolean         setEnable;         
            if(METSalesLine::hasExtractedLine(SalesLine))
            {
                setEnable = false;              
            }
            else
            {
                setEnable = true;               
            }
            #SetEnabled(formcontrolstr(SalesTable, LineStripNew),  setEnable);
            #SetEnabled(formcontrolstr(SalesTable, ButtonLineQuickQuote),  setEnable);
            #SetEnabled(formcontrolstr(SalesTable, RetailAddItemMenuItem),  setEnable);
            #SetEnabled(formcontrolstr(SalesTable, LineStripDelete),  setEnable);
            #SetEnabled(formcontrolstr(SalesTable, SalesUpdateRemain),  setEnable);
        }
        
    }

    /// </summary>
    /// MPJ_24819_SOParametersAndCancelLinePickList
    /// Control “Update Line > Delivery Remainder” button
    /// </summary>
    protected void enableLineRetailActions()
    {
        next enableLineRetailActions();
        if(METCustParameters::find().DisableSOLineEdit)
        {    
           
            #SetEnabled(formcontrolstr(SalesTable, retailAddItemMenuItem), !METSalesLine::hasExtractedLine(salesLine));
           
        }       

    }
